-- 2220 🏋️ Exercises from the book "coaching-the-tiki-taka-style-of-play" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'coaching-the-tiki-taka-style-of-play');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('Barcelona circle rondo with 2 pressers', 'rondo', 'overload', 'in_possession', 56, 58, 'Practice 1', 'Laureano Ruiz / Carles Rexach (FC Barcelona)', 'High-tempo possession warm-up building quick short passing, body shape and quick thinking under pressure, with fast changeovers that mimic transition.', 'Outside players spaced round a circle with 2 (up to 3-4) defenders in the middle; diagram shows about 9 outside v 2 inside. Coach keeps spare balls ready so play never stops.', 'Outside players keep the ball with short passes while the middle players press and try to intercept (no tackling). Players learn first, second and third line passes (around vs split through the two defenders) and the one-touch rebound pass. When the ball is lost, both the player who gave it away and the one who passed to him swap in immediately with the two defenders.', 'Middle players press and intercept, do not tackle. Defenders carry bibs (not worn) and drop them on changeover; changeover at full speed with no walking. Only pause to give a coaching point. Sizes range from 4v2 and the common 5v2 up to game-like numbers.', '1) No player may play two first line passes in a row. 2) Limit to 2-touch then 1-touch. 3) Change area size, numbers and player positions to mirror game positions (e.g. centre-backs and wide players round a square, then two midfield units inside - see Practice 10).', 'Let players own it as a regular team routine; receive on the foot furthest from the defender; look for second and third line passes; the two pressers work together to block second line passes and tempt the passer, pouncing on first and third line passes; use half-touch rebound passes; never stop the practice, stress transitions.', '5v2 typical (diagram ~9v2), 4v2 up to game-sized', 6, 13, NULL, NULL, NULL, NULL, false, false, false, NULL, 10),
  ('Double rondo with switching overload', 'rondo', 'overload', 'in_possession', 59, 59, 'Practice 2', 'FC Barcelona', 'High-tempo possession warm-up under pressure that also brings in transition and playmaking themes.', 'Two adjoining rectangles, each with players on the outside (6 in total per the book''s layout), one overload player in the middle and two pressing defenders in the opposite half.', 'Players keep the ball in one rectangle with the central overload player helping, then switch it to the other rectangle. After the switch the two pressers join the outside and the two central outside players become the new pressers.', NULL, 'Builds on Practice 1 (the rondo). Coach can change how many passes are needed before the switch is allowed.', NULL, '6 outside + 1 overload + 2 pressers', 9, 9, NULL, NULL, NULL, NULL, false, false, false, NULL, 20),
  ('Adjacent passing square with side support', 'passing_unopposed', 'unopposed', 'in_possession', 60, 60, 'Practice 3', 'FC Barcelona', 'Technique-to-skill passing pattern: support angles and coordinated movement around a square.', '10 yard square with 4 players on the outside, each limited to one side and sitting in the corner nearest the ball; optional 5th player in the middle.', 'The ball moves round the square; the two players on the sides next to the ball slide to support in line with the ball while the opposite player stays in line too. Direction can switch by laying the ball back to the player who just passed.', 'No passes straight across the square to the far side; pass only to the side supports. Aim for 2 touches.', 'Part B: add a defender in the middle to make it opposed. Change the square size to raise the intensity.', 'Two touches to buy time to move; receive across the body to open up options.', '5-6', 4, 6, '10 x 10 yards', 9.1, 9.1, NULL, false, false, false, NULL, 30),
  ('Laureano Ruiz 3v1 triangle keep-ball', 'rondo', 'overload', 'in_possession', 61, 61, 'Practice 4', 'FC Barcelona (Laureano Ruiz)', 'Keep the ball in a tight square 3v1 at high intensity while holding a triangle shape.', '10 x 10 yard square, 3 attackers forming a triangle, 1 defender inside, a resting player waiting outside.', 'The three keep a triangle (which can rotate around the square) and move the ball on 1-2 touches against the middle man. Each spell lasts at most 60 seconds, then the middle man rests and the resting player swaps in.', '1-2 touches where possible, not strictly enforced. Max 60 seconds per cycle.', 'Change the square size to suit the players; add a neutral player for extra mental load.', 'Receive across the body to open options.', '3v1 + 1 resting', 5, 5, '10 x 10 yards', 9.1, 9.1, NULL, false, false, false, NULL, 40),
  ('4v4 plus two end-line rebounders', 'possession', 'overload', 'in_possession', 62, 62, 'Practice 5', 'AFC Ajax', 'Dominate possession using the whole space with help from two end-line rebound players; can teach pressing triggers.', 'Rectangle with 4v4 inside and one neutral rebounder (kaaster) on each end line who can only move along that line.', 'The team in possession uses the end rebounders, who play quickly back to the team that fed them. Best with 10 players, minimum 8.', 'Rebounders return the ball to the team that passed to them.', 'Rebounders become pressers when a team fails at a set theme (shielding, poor first touch, rushing, not making space), then rotate with an inside player.', 'Coach may call out triggers; vary numbers, touches for rebounders; add triggers like ''heavy pass means support is behind you''.', '4v4+2', 8, 10, NULL, NULL, NULL, NULL, false, false, false, NULL, 50),
  ('4v4+1 corner to corner possession', 'positional_game', 'overload', 'in_possession', 63, 63, 'Practice 6', 'AFC Ajax', 'Passing, moving in possession and pressing when outnumbered.', 'Square with a corner player (kaaster) for each team in every corner, teams'' corners diagonally opposite; each team has 2 central players plus one central neutral playmaker.', 'A team works the ball from one of its corner players to the diagonally opposite corner player, needing at least 3 passes in the middle zone. Defenders try to stop it while outnumbered.', 'Corner players 1 touch. Neutral may be limited to 1-2 touches. Minimum 3 passes before reaching the far corner.', 'Vary the number of passes, touches for neutral/corner players and players per team.', 'Positioning to give the one-touch corner players options; the neutral should show off-ball movement as a playmaker.', '4v4+1', 9, 9, NULL, NULL, NULL, NULL, false, false, true, NULL, 60),
  ('Four-square shielding 3v1 with neutrals', 'technical', 'overload', 'in_possession', 64, 64, 'Practice 7', 'FC Barcelona', 'Shield the ball and wait for support to arrive.', 'Area split into 4 squares, one player from each side in every square, plus 2 neutral players.', 'The 2 neutrals make a 3v1 in a square and play 6 passes, then pass into a player in another square, who shields from his opponent until the neutrals arrive. If the opponent wins it, he plays into a new square and the cycle restarts.', '6 passes before switching squares.', 'Start as a free passing drill with 3-4 groups (one passes in, one lays off, the third dribbles into another square), then progress to 3v1 in each box with support from the sides, not corners.', 'Coach the shielding player on starting position, first touch and body shape.', '8 + 2 neutrals', 10, 10, NULL, NULL, NULL, NULL, false, false, false, NULL, 70),
  ('6v6 three goals game', 'small_sided_game', 'opposed', 'out_of_possession', 65, 65, 'Practice 8', 'AFC Ajax', 'Defend three goals at once and regain the ball with equal numbers.', '6v6 in a rectangle with 3 small goals placed around the area (as in the diagram).', 'Teams play a normal game into any goal. Defenders may cover goals but then leave a 6v3 in the middle. Winner is most goals, or if level the team with more possession.', 'Possession decides a draw, so teams have an incentive not to just cover goals.', 'Allow play in the space behind the goals, hockey style.', 'Players find their own balance between guarding goals and winning the ball; help the defending team find a shape; add a neutral for the team in possession if they struggle.', '6v6', 12, 13, NULL, NULL, NULL, NULL, true, false, true, NULL, 80),
  ('5v4 breaking out of middle third', 'phase_of_play', 'overload', 'in_possession', 66, 66, 'Practice 9', 'FC Barcelona', 'Link ball circulation in midfield with attacking play.', 'Zone on the halfway line with 3v3 plus one extra player outside for each team; a goalkeeper in the goal ahead, attackers and defenders positioned in front of goal.', 'The team in the zone plays at least 5 passes and then plays into an attacker to outnumber the defence and attack the goal. Up to 2 attackers can join from the zone; at first no defenders may leave.', 'Min 5 passes. Striker''s first touch is free (unchallenged), the defender can contest from the second. Max 2 attackers join.', 'Vary passes, number of attackers/defenders allowed out of the zone and defender restrictions.', 'Focus on off-ball movement and angles of runs.', '5v4 + GK', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 90),
  ('Position-specific 8v8+1 back-to-back possession', 'possession', 'overload', 'in_possession', 67, 67, 'Practice 10', 'Liverpool FC (Brendan Rodgers)', 'Build-up play with players in their real positions from a 4-3-2-1 shape.', '25 x 50 yard area split by a halfway line; each team has its centre-backs on the end lines and full-backs on the sides outside the area, midfielders inside, plus one neutral playmaker.', 'The team in possession works the ball from one of its centre-backs across halfway and back to a centre-back, imitating non-directional control of the ball. Outside players control and quickly play back inside.', 'Neutral cannot be marked. Inside players may only shadow or block outside players and can tackle only if the ball enters the central space through a poor touch.', 'Different touch limits per position or group (outside players only pass inside); require a minimum number of passes before returning to a centre-back.', 'Get players used to their position on the pitch and solving problems from it.', '8v8+1', 17, 17, '25 x 50 yards', 45.7, 22.9, NULL, false, false, true, NULL, 100),
  ('Gridded 5v5 four goal game', 'small_sided_game', 'opposed', 'in_possession', 68, 68, 'Practice 11', 'Villarreal CF', 'Problem solving in possession under strategic passing restrictions.', 'Grid of small squares (about 30 x 30 yards for 5v5) marked with flat cones and colours, one goal on each of the 4 sides; scoring zones are the 2 grids nearest each goal.', '5v5; either team can score in any of the four goals, but can only shoot from inside the scoring zones.', 'No pass to a team-mate in the same horizontal or vertical line of squares as you. Defenders may be kept out of the scoring zones if the game stalls.', 'Add a neutral playmaker free of the line rule; change zones, players, min/max passes.', 'Players invent their own ways to find space; use flat markers so the grid does not stop play.', '5v5', 10, 11, 'approx 30 x 30 yards', 27.4, 27.4, NULL, true, false, true, NULL, 110),
  ('3-zone overloads small sided game', 'small_sided_game', 'overload', 'in_possession', 69, 69, 'Practice 12', 'Villarreal CF', 'Show how a system creates overloads in each third (based on a 3-4-3 / 3-5-2 idea).', 'Pitch in thirds, 4v4 + 2 neutrals + 2 GKs: 2 defenders and GK v 1 striker at the back, 3 midfielders v 2 in the middle, 1v1 up front.', 'Teams stay in their thirds and must play through them; the defending team can counter and skip the middle. The neutrals play for whoever has the ball. A midfielder who plays a one-two with the striker may enter the final third to make 2v1.', 'Zonal restrictions at first; midfielder unlocks into the final third only via a one-two.', 'Remove the zones but players keep shape; scan every 3-4 seconds before receiving.', 'Pass weight signals where support is; give support to the side, behind and ahead of the ball carrier.', '4v4+2 neutrals+2 GKs', 12, 12, NULL, NULL, NULL, NULL, true, true, true, NULL, 120),
  ('Four-zone passing through the lines', 'positional_game', 'opposed', 'in_possession', 70, 70, 'Practice 13', 'Liverpool FC', 'Pass through the lines while the opposing midfield trio blocks passing lanes together.', 'Area split into 4 horizontal zones with 3 players in each, teams alternating zone by zone (two teams of 6).', 'Each zone must make at least 2 passes before passing through the opposing zone to team-mates in the next own zone, giving the blockers time to reshape.', 'Players stay in their zones; no tackling, only shadowing within the zone. Ground passes.', 'If too easy, move a possession player into the blocking midfield; add touch or pass limits per zone.', 'Encourage ground passes; help the team without the ball with shape and how to win it back.', '6v6', 12, 12, NULL, NULL, NULL, NULL, false, false, true, NULL, 130),
  ('Thirds channels 3v3 with 1v1 to mini goals', 'small_sided_game', 'opposed', 'in_possession', 71, 71, 'Practice 14', 'FC Barcelona', 'Patience in possession to pull opponents out of shape, then a 1v1 to score.', 'Pitch split into 3 vertical channels with 3 mini goals at each end; 3 attackers in their half and 3 defenders, one per channel, beyond the red cone line.', 'The 3 pass among themselves to unbalance the blockers, then one dribbles into a channel, beats his defender 1v1 and scores in a mini goal. An interception switches roles.', 'Tackling only once the attacker enters the opposition half (past the red cones).', NULL, 'Spot when an opponent is out of position; patience; receive with open body, few touches, middle player acts as playmaker.', '3v3', 6, 6, NULL, NULL, NULL, NULL, true, false, true, NULL, 140),
  ('10v4 switching through middle third', 'positional_game', 'overload', 'in_possession', 72, 72, 'Practice 15', 'AFC Ajax', 'Possession and passing through the midfield line.', 'Area in thirds; two teams of 5 (4 in each end third and 1 in the middle zone) plus 4 defenders in the middle zone.', 'The team in possession must move the ball to the opposite third, using the middle third at least once before each switch. When the defenders win it 3 times, roles change.', 'Players stay in their zones; points only when the ball goes through the middle and out to the other side (e.g. 2 points through the middle, 1 otherwise).', 'Start with all 10 as one team, one ball into the middle every 2 switches; then reds may only pass to reds and blues to blues (middle defenders mark space only); move to one touch in the middle; time limits (switches per minute).', 'Make the pitch big in possession, compact without it; set restrictions to the players'' ability.', '10v4', 14, 14, NULL, NULL, NULL, NULL, false, false, true, NULL, 150),
  ('7v7 three zone touch-limited game', 'small_sided_game', 'opposed', 'in_possession', 73, 73, 'Practice 16', 'AFC Ajax', 'A normal 7v7 with touch and zone restrictions per third to shape the way teams build.', 'Pitch in three zones (defence, midfield, attack) with a goal and GK at each end.', 'Start with players restricted to their own zones, then let some break into other zones, then set touch counts per zone (e.g. 3 touches at the back, 1 in midfield, 2 in attack) to encourage building from the back and off-ball movement.', 'Touch limits by zone; avoid one touch in the final third because finishing needs control.', 'Free up positional rules once touch conditions are set.', 'Balance it to your objectives; play quickly entering the final third; keep possession and maximise chances.', '7v7', 14, 14, NULL, NULL, NULL, NULL, true, true, true, NULL, 160),
  ('4v4+2 runs in behind to end zones', 'positional_game', 'overload', 'in_possession', 74, 74, 'Practice 17', 'AFC Ajax', 'Timing of runs in behind and weight of pass into an end zone.', 'Central area with an end zone at each end (about 6 yards deep) and a side zone on each flank holding a neutral player; 4v4 in the middle.', 'Teams keep the ball and look for a run in behind timed with a pass into the end zone to score, often after using a side neutral. The end zone line acts as an offside line.', 'Neutrals stay in their side zones and cannot be tackled. Offside at the end zone line.', 'Restrict the neutrals (no assists, limited touches).', 'Let the game teach; a straight run suits a diagonal pass and a diagonal run suits a straight pass.', '4v4+2', 10, 10, NULL, NULL, NULL, NULL, false, false, true, NULL, 170),
  ('7v7 with free wide safe zones', 'small_sided_game', 'opposed', 'in_possession', 75, 75, 'Practice 18', 'FC Barcelona', 'Use the full width in your own half via unopposed side zones.', '7v7 with GKs; side channels in each half act as safe zones for the team building from that end.', 'Defenders building up can step into the side zones in their own half, where they cannot be marked or tackled, using them and the GK for pressure relief before playing through the centre.', 'Opponents cannot enter the other team''s safe zones; must attack centrally. Receivers in safe zones play quickly (2-3 touches) but need not rush if no pass is on.', NULL, 'Ask: if we make the pitch big in possession, what do we do when defending? (Keep it small.) Mark wide spaces before the ball goes out while protecting the centre.', '7v7', 14, 14, NULL, NULL, NULL, NULL, true, true, true, NULL, 180),
  ('7v7+2 playing out with defensive safety zone', 'small_sided_game', 'overload', 'in_possession', 76, 76, 'Practice 19', 'FC Barcelona', 'Use specific spaces (a back safety zone and wide neutrals) to build from the back and relieve pressure.', '7v7 in thirds with GKs, 2 neutral players on the sides; the defensive third is a safety zone for the centre-backs and GK.', 'Centre-backs and GK can play in the safety zone free of pressure, so opponents drop into an organised block. Teams must still keep trying to create chances.', 'Neutral wide players play quickly, possibly 2-3 touches.', 'Safety zone usable only after the ball has first crossed halfway.', 'Focus coaching on the defending team''s organisation; wide neutrals stretch play.', '7v7+2', 16, 16, NULL, NULL, NULL, NULL, true, true, true, NULL, 190),
  ('8v9 breaking down a deep block', 'phase_of_play', 'opposed', 'in_possession', 77, 77, 'Practice 20', 'FC Barcelona', 'Break down a disciplined deep defensive block; defenders practise protecting and countering.', 'Half a pitch: 8 attackers (2 full-backs, 3 central mids, 3 forwards) v 9 defenders (two lines of 4 plus GK); 2 mini goals on halfway for the defending team''s counters.', 'Attackers try to unpick the block with dribbles, one-twos, a deliberate ''false touch'' to draw defenders and wide play, with a deep playmaker controlling possession. Defenders protect the centre and by-line and counter into the halfway goals.', 'Wide areas are a no-assist zone except from the by-line when isolated 1v1.', NULL, 'Defence protects central zone and by-line; attack uses a deep-lying playmaker who also screens counters.', '8v8+GK', 17, 17, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 200),
  ('6v6 unopposed positional pattern play', 'passing_unopposed', 'unopposed', 'in_possession', 78, 78, 'Practice 21', 'Swansea City FC', 'Comfort in the positional system and ball circulation in deeper areas.', 'Full pitch, two teams of 6 placed in set positions in zones marked with cones; extension of practices 25 and 26.', 'A team passes to every player in a set pattern then hands the ball to the other team, who copy the pattern they just watched.', NULL, NULL, 'Body position and first touch; check around before receiving as if opponents were there; keep distances (about 20 yards on a full pitch) and move as a unit.', '6v6 (unopposed)', 12, 12, 'full pitch', NULL, NULL, NULL, false, false, false, NULL, 210),
  ('8v6 playing out from goalkeeper', 'phase_of_play', 'overload', 'in_possession', 79, 79, 'Practice 22', 'Swansea City FC', 'Build up from the goalkeeper against pressure.', 'GK, 4 defenders and 3 midfielders (4-3-3) against 2 attackers and 4 midfielders (4-4-2); 3 mini goals near halfway represent the three forwards.', 'Each phase starts with the GK. The team in possession uses its spare man to play out and score in one of the 3 goals, which count only from within 5 yards. Goals may be marked.', 'Goals only from within 5 yards.', 'Add 2 more defenders as full-backs, or change the defending team''s formation.', 'Defenders balance high press against guarding goals; attackers stay patient and dominate the ball.', '8v6', 14, 16, NULL, NULL, NULL, NULL, true, true, true, NULL, 220),
  ('Midfielder timing runs in block pattern', 'passing_unopposed', 'unopposed', 'in_possession', 80, 80, 'Practice 23', 'Athletic Bilbao', 'Pattern play for the central midfielder''s movement within a middle-third block.', '2 defenders (centre-backs) and 1 midfielder, mannequins as the opposing block in the middle third.', 'Players run a set numbered passing sequence at match tempo; the midfielder makes short timed sprints into space between the mannequins. The next cycle mirrors it from the other side, continuously.', '2 touches each.', NULL, 'Short, well-timed sprints into space between markers; curved runs; disguise the pass into midfield.', '3', 3, 3, NULL, NULL, NULL, NULL, false, false, false, NULL, 230),
  ('Compact block midfield pattern play', 'passing_unopposed', 'unopposed', 'in_possession', 81, 81, 'Practice 24', 'Athletic Bilbao', 'More complex pattern play in a congested midfield zone.', 'Like Practice 23: 2 ball-playing defenders and a midfielder with poles representing a tight block.', 'A 5-pass pattern with the midfielder sprinting into gaps, then mirrored from the opposite side, continuously.', '2 touches.', NULL, 'Short timed sprints, curved runs, disguised passes; accurate weight.', '3', 3, 3, NULL, NULL, NULL, NULL, false, false, false, NULL, 240),
  ('Back four and pivot shape when playing out', 'passing_unopposed', 'unopposed', 'in_possession', 82, 82, 'Practice 25', 'FC Barcelona', 'Comfortable passing network between the back 4 and the deep-lying midfielder.', 'Back 4 plus deep controller in marked stations in front of goal; full-backs receive on the touchline, players stay about 20 yards apart.', 'Players shift within their stations depending on where the ball is (all shift left when it goes to the left-back). On the coach''s call they break forward via a full-back or controller, then on ''start again'' drop back into shape as a unit.', '2-3 touches.', NULL, 'Receive across the body; confident, well-weighted passes; high standards and intensity.', '5', 5, 5, NULL, NULL, NULL, NULL, false, false, false, NULL, 250),
  ('Back five shape from a throw-in', 'passing_unopposed', 'unopposed', 'in_possession', 83, 83, 'Practice 26', 'FC Barcelona', 'Positioning and passing pattern starting from a throw-in as a game-like restart.', 'Same stations as Practice 25 (back 4 plus controller), with a full-back taking a throw-in.', 'The throw goes to a centre-back who has dropped into a deep full-back spot or to the controller, who plays the shortest pass. The ball is worked across the pitch 3 times, then the throw-in is repeated from the opposite flank; a centre-back receiving in the full-back spot moves to the zone edge nearest the middle on his second touch so the thrower can go wide.', '2-3 touches.', NULL, 'Receive across the body; confident, weighted passes; high intensity.', '5', 5, 5, NULL, NULL, NULL, NULL, false, false, false, NULL, 260),
  ('Three-team one-touch combo and shot', 'finishing', 'unopposed', 'in_possession', 84, 84, 'Practice 27', 'Liverpool FC', 'Shoot from outside the box after a quick series of one-touch passes.', 'Three teams of 4 in three lanes outside the box (right foot, central, left foot), a GK in goal.', 'The first player passes forward and gets the ball back to shoot only after the set sequence of one-touch passes. Teams take turns and rotate positions clockwise; most goals wins.', 'One-touch passes; shooter up to 3 touches. Right foot in the right lane, left foot in the left, either centrally.', NULL, 'Use the weaker foot; body, arm and head position and shot type; keep it fun and realistic.', '12 + GK in 3 teams of 4', 13, 13, NULL, NULL, NULL, NULL, true, true, true, NULL, 270),
  ('3v3+GK feeding the front three', 'finishing', 'opposed', 'in_possession', 85, 85, 'Practice 28', 'FC Barcelona', 'Forwards learn to turn against tight markers under high pressure and combine to score.', '3 forwards on the edge of the 6 yard box with 3 defenders tight behind them, GK in a full goal; 2 wide mini goals at the other end for defenders; coach or spare player feeds.', 'The feeder plays into a striker''s feet or chest; the 3 forwards combine to score. If the defenders win it they counter quickly into a mini goal. After a goal or ball out, everyone resets.', 'Defenders must counter fast, not build slowly.', 'Coach varies the angle, height and speed of the feed.', 'Striker shields patiently until he can turn; watch the movement of the other two to make space.', '3v3+GK', 7, 8, NULL, NULL, NULL, NULL, true, true, true, NULL, 280),
  ('3v3+GK finding space with outside kaasters', 'finishing', 'opposed', 'in_possession', 86, 86, 'Practice 29', 'Wigan Athletic FC', 'Forwards find space in behind tight markers in a crowded box, with third-man runs.', 'Penalty area 3v3 plus GK, with 3 rebound players (kaasters) placed outside the area; coach at the start.', 'The coach passes to a kaaster who feeds a forward; the 3 forwards combine with the kaasters, who try to play the ball in behind or over the defence.', 'Offside applies. Kaasters limited to 2 touches, later 1. Optional: defenders who win it become attackers; conditions like no one-two assists.', 'Move kaaster positions; one-touch kaasters; game conditions.', 'Third-man movement; think two steps ahead; disguise and fake runs (double fake) to lose a marker.', '3v3+3+GK', 10, 10, 'penalty area', NULL, NULL, NULL, true, true, true, NULL, 290),
  ('Verheijen sprint race to ball and finish', 'finishing', 'opposed', NULL, 87, 87, 'Practice 30', 'Feyenoord (Raymond Verheijen)', 'Short match-like sprints with an end product: beat the opponent to the ball and score under pressure.', 'Pairs at each end of a pitch with a goal and GK at each end; coach between the pair.', 'The coach plays the ball forward (short, long, high or along the ground, fair to both); both sprint and the first there attacks while the other defends, finishing on goal.', 'About 10 seconds rest before the next sprint; no queues longer than the recovery time.', NULL, 'Control, shield or shoot under control despite the speed; aim for a turnover of about 10 seconds per pair.', 'pairs + 2 GKs', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 300),
  ('Three-zone 1v1 moves-to-beat dribbling', 'one_v_one', 'opposed', 'in_possession', 88, 88, 'Practice 31', 'AFC Ajax', 'Creativity in 1v1 duels and rehearsing new moves in match-like conditions.', '3 players in separate zones: a deep defender, a second defender near the middle and an attacker.', 'The deep defender passes to the attacker, who plays a quick one-two with the second defender and is pressed straight away, aiming to beat him with one touch. The deep defender then approaches and the attacker uses a set move to beat him and dribble into the end zone. Players rotate.', 'Defender jockeys with little pressure at first, then tackles for real.', 'Coach introduces new moves (Roulette, Elastic, Chop, Step Over, La Croqueta, change of pace).', 'Moves at pace, aggressive, ball kept moving; know the purpose of each skill.', '3', 3, 3, NULL, NULL, NULL, NULL, false, false, true, NULL, 310),
  ('Three-station feint and interchange', 'passing_unopposed', 'unopposed', 'in_possession', 89, 89, 'Practice 32', 'FC Barcelona', 'Introduce the dummy movement to lose your marker.', '6 players, 2 at each of three cone stations A, B and C.', 'A passes to B, who returns it; A passes to C, who dribbles back to A. Players at B and C make a sharp fake movement away from the ball before coming back to receive. Players move on to the next station after their task (A to B, B to C, C to A).', '1-2 touches when receiving across the body.', NULL, 'Feint must be convincing and not spoil the next action; high tempo, minimal queues.', '6', 6, 6, NULL, NULL, NULL, NULL, false, false, false, NULL, 320),
  ('4v4 block defending three mini goals', 'defending', 'opposed', 'out_of_possession', 90, 90, 'Practice 33', 'Villarreal CF', 'Teach the value of an organised defensive block (e.g. the midfield line of a 4-4-2).', '4 attackers v 4 defenders guarding 3 mini goals behind them; defenders play in the area between attackers and goals.', 'Let players play freely first, defenders only told to stop the ball reaching the goals. Then stop and work out angles to block; attackers play 8-10 yards from the goals and defenders mark space, not players.', 'Can add an extra possession player to outnumber the defenders.', 'Walk through the block first, build to match speed.', 'Demonstrate block shapes; body shape to make the opposition predictable.', '4v4', 8, 9, NULL, NULL, NULL, NULL, true, false, true, NULL, 330),
  ('3v3 high intensity transition game', 'transition', 'opposed', 'to_defend', 91, 91, 'Practice 34', 'Villarreal CF', 'Push players to switch from attack to defence as fast as they switch from defence to attack.', 'Small pitch with halfway line and a goal plus GK at each end; balls around the edges; 3 teams, one resting and collecting balls.', 'Normal 3v3. When a team loses the ball, its most advanced player must sprint to the opposition by-line and back to his own halfway line before he can defend, leaving a 2v1 meanwhile.', 'Player furthest forward on the losing team runs to the by-line and back to halfway before rejoining.', NULL, 'Age-appropriate space for 2v2 outfield; urgency to recover position after an attack; rotate the resting team.', '3v3 + GKs, 3 teams', 8, 11, NULL, NULL, NULL, NULL, true, true, true, NULL, 340),
  ('8v4 three-zone switch through screening pair', 'possession', 'overload', 'in_possession', 92, 92, 'Practice 35', 'FC Barcelona', 'Possession under conditions and switching play through a central zone.', 'Area (flexible size) in 3 zones: two end zones for the team in possession (4 in each) and a central zone holding the defending team; 2 defenders press in the end zone, 2 screen in the middle.', 'Pressing pair goes into the end zone with the ball; the 4 attackers make a set number of passes then switch through the middle to the other end while the 2 screeners try to block. If the middle intercepts, they swap with the 4 at the end where the ball was lost.', 'Set number of passes before switching.', 'Keep the pass count low for high pressing; restrict the middle players if too hard; only 1 presser if possession is too difficult.', 'Area is narrowed to mimic defenders sitting deep and compact at the edge of the box.', '8v4', 12, 12, NULL, NULL, NULL, NULL, false, false, true, NULL, 350),
  ('5v2 square into 8v5 transition game', 'transition', 'overload', 'to_attack', 93, 93, 'Practice 36', 'FC Barcelona', 'Keep the ball with a numerical advantage and switch quickly between keeping and winning it back.', 'Central square big enough for 5v2, inside a larger area with 6 more teammates of the chasers on the outside.', '5 keep the ball from 2 chasers in the square. If the 2 win it, they play out to any of their 6 teammates outside and it becomes 8v5 in the whole area. When the 5 win it back, the 5v2 in the square restarts.', '1 point per 5 passes (fewer if both teams struggle). Transitions unopposed at the moment the ball goes into or out of the square.', 'Let players enter the central area on a trigger (poor touch, poor pass).', 'Use the whole space and collective positioning; use an unmarked playmaker in the large area.', '8v5', 13, 13, NULL, NULL, NULL, NULL, false, false, false, NULL, 360),
  ('7v7 three zones with blockers and receivers', 'possession', 'opposed', 'in_possession', 94, 94, 'Practice 37', 'AFC Ajax', 'Possession under high pressure through a ring of blockers.', 'Three zones: a central square with 3v3, a blockers'' ring around it, and an outer receivers'' zone; each zone at least 5 yards deep.', 'Central players pass out to one of their 2 receivers and get it back into the square for a point. Receivers find space despite being marked by a blocker. Blockers of the team in possession act as one-touch rebounders.', 'Nobody leaves their zone. Receivers max 3 touches and play back in quickly; blockers 1 touch.', 'Receivers may use their blockers to pass back in (first-touch reward); max/min passes in the centre; add a neutral central player.', 'Disguised movement, maximise space, careful angles of passes and movement.', '7v7', 14, 15, NULL, NULL, NULL, NULL, false, false, true, NULL, 370),
  ('Front five pressing shift on coach''s call', 'defending', 'unopposed', 'out_of_possession', 95, 95, 'Practice 38', 'FC Barcelona', 'Organised team press movement for the front 3 and central midfield pair of a 4-3-3.', '5 players on rings in their own half, mannequins as opponents, coach behind, next 5 resting.', 'The coach calls ''right'', ''left'' or ''central'' (or cone colours) and the 5 sprint to the matching press positions keeping their distances. After 5-6 calls the coach shouts ''cleared'' and they sprint back to start; the next group goes.', NULL, 'Start at walking pace until the shape is right, then match intensity; also works for pre-season fitness.', 'Highest intensity; demonstrate with tactics board or mannequins.', '5 at a time (groups of 5)', 5, 10, 'half pitch', NULL, NULL, NULL, false, false, false, NULL, 380),
  ('7v7 defensive block scoring zone game', 'small_sided_game', 'opposed', 'out_of_possession', 96, 96, 'Practice 39', 'Liverpool FC', 'Use pressing as a way to slow the opponent''s attack with a back 4 and midfield trio.', '7v7, two mini goals at each end with a 5 yard shooting zone in front of each end.', 'Free play first, then match conditions: attackers must get into the shooting zone to score; defenders limit them, win it and counter into the opposite goals.', 'Shots only from inside the 5 yard zone.', NULL, 'Quick attack-to-defence transition (2 goals to defend); compact block; use a playmaker and false touch to break it; press only when the moment is right.', '7v7', 14, 14, NULL, NULL, NULL, NULL, true, false, true, NULL, 390),
  ('5v5 attackers drop to halfway zone', 'transition', 'opposed', 'to_defend', 97, 97, 'Practice 40', 'AFC Ajax', 'Attackers drop back into position after losing the ball.', '5v5 with two mini goals and a scoring zone at each end and a 3 yard zone on halfway.', 'After losing the ball, the attacking 3 drop into the halfway zone and stay there until the ball is won, blocking passes through them. Central defenders cannot cross into the other half, so a 3v2 forms if the ball gets through.', 'Attackers cannot leave the halfway zone until the ball is won.', 'Add pressing rules like the 6 second rule (press hard for 6 seconds after losing it, then drop into the zone).', 'Block passing lanes from inside the zone; constant communication and discipline.', '5v5', 10, 10, NULL, NULL, NULL, NULL, true, false, true, NULL, 400),
  ('7v7 pressing triggers game', 'defending', 'opposed', 'out_of_possession', 98, 98, 'Practice 41', 'FC Barcelona', 'Introduce pressing triggers to a team.', '6v6 outfield plus GKs (or a 5 yard scoring line instead); up to 3 extra pressers on the sideline.', 'Play normally until a trigger (coach call or game cue) lets the defending team press aggressively to win the ball. If the attackers keep it for 8 seconds, the defence drops back into a block.', '8 seconds of possession ends the press.', 'Up to 3 sideline players join the defending team on a trigger to overload; rotate them for intensity.', 'Introduce triggers gradually and guide players until they read them.', '6v6 + GKs (+3)', 12, 17, NULL, NULL, NULL, NULL, true, true, true, NULL, 410),
  ('7v7 six-second press game', 'defending', 'opposed', 'out_of_possession', 99, 99, 'Practice 42', 'FC Barcelona', 'Understand pressing rules and triggers through coach-set conditions.', '7v7 with GKs and a marked central zone across the middle third.', 'On the coach''s ''press'' call the defending team presses aggressively high for 6 seconds. If the attackers keep the ball through that spell, defenders drop into a disciplined block in the central third. If attackers get into the central zone with the ball, defenders choose between block and press.', 'Press lasts 6 seconds, then drop into the central-third block.', 'Start with no conditions so defenders feel the need for organisation; coach brings in different block types.', 'Use the format to teach stepping out of the block to press; reinforce the disciplined block first.', '7v7', 14, 14, NULL, NULL, NULL, NULL, true, true, true, NULL, 420),
  ('7v7 pressing attacking corner zones', 'defending', 'opposed', 'out_of_possession', 100, 100, 'Practice 43', 'FC Barcelona', 'Control the game without the ball as an organised pressing team.', '7v7 with GKs and 4 corner pressing attacking zones (PAZ), one in each corner.', 'Each attack starts with the GK''s first pass out into a PAZ before the defending team may press. If the defenders force the team in possession into a PAZ, they win possession via a throw-in or kick-in.', 'Defence may press only after the GK has played into a PAZ.', 'Team in possession may not pass back to its GK; minimum 5 passes before crossing halfway.', 'Defensive shape and recognising triggers to press forward.', '7v7', 14, 14, NULL, NULL, NULL, NULL, true, true, true, NULL, 430),
  ('3v3 into 6v3 three-phase transition', 'transition', 'overload', 'to_defend', 101, 101, 'Practice 44', 'AFC Ajax', 'Switch from attacking to defending fast and match the speed of transition.', 'Pitch in 3 zones with 3 players in each zone and a GK at each end (9 + 2 GKs).', 'Phase 1: middle trio dribbles and attacks the defending trio. When they score or lose it, the ball goes to the far-end trio, who attack against 6 defenders (phase 2). Then it restarts the other way (phase 3). Players defend only once the ball enters their zone.', 'Players become active defenders only when the ball enters their zone.', NULL, 'Defensive discipline and shape rather than diving in; show attackers wide away from goal.', '9 + 2 GKs', 11, 11, NULL, NULL, NULL, NULL, true, true, true, NULL, 440),
  ('2v2 counter attacks from halfway zone', 'transition', 'opposed', 'to_attack', 102, 102, 'Practice 45', 'Swansea City FC', 'Forwards receive and beat defenders in front of them on the counter.', 'Full pitch (age-appropriate), 8 outfield players and GKs, an unopposed zone either side of halfway where attackers pick up the ball; 2 defenders in each final third.', 'GK passes to a defender, who feeds an attacker in the central zone; the attackers turn and go 2v2 against the defenders to score. After a goal or loss the ball goes to the other pair waiting near halfway to attack the opposite goal.', 'Shoot inside the box, or from just outside if defenders sit too deep. Full pace.', 'Vary numbers of attackers or defenders.', 'Movement off the ball to make space for a teammate; inactive time is rest but take a good starting position.', '8 + 2 GKs', 10, 10, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 450),
  ('2v1 then 3v2 quick transition', 'transition', 'opposed', 'to_attack', 103, 103, 'Practice 46', 'FC Barcelona', 'Quick transition: 2 attack 1, then immediately defend against 3.', 'Half pitch with a goal and GK at each end; 2 attackers, 1 defender, 2 resting team-mates of the defender on the goal line.', 'The defending GK kicks over halfway; the 2 attackers sprint back, receive, turn and try to beat the lone defender and score. If the defender wins it, his 2 team-mates sprint on to make 3 attackers, and it becomes 3v2 against the original pair.', 'Offside and other conditions set by the coach; attackers let the defender take an intercepted ball unopposed.', 'Vary numbers (e.g. 3v2 becoming 3v5).', 'Speed of play and decision making on the ball.', '2v1 / 3v2 + GKs', 7, 7, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 460),
  ('7v7 false nine drop zone', 'small_sided_game', 'opposed', 'in_possession', 104, 104, 'Practice 47', 'FC Barcelona', 'An attacker drops into unmarked space to receive and turn against a defender.', '7v7 with GKs and a 3 yard central zone across the middle that defenders cannot enter; 3v3 in each end zone.', 'The ball must pass through the central zone before reaching the final third. An attacker drops into the zone to receive and turn and cannot be tackled until he leaves it, then dribbles or passes on.', 'Player in the zone max 2 touches and max 2 seconds there without the ball; only 1 attacker in the zone at a time.', 'Only the first touch is free, then a defender may enter the zone to press.', 'Timing of the run; think about the direction of the first touch.', '7v7', 14, 14, NULL, NULL, NULL, NULL, true, true, true, NULL, 470),
  ('Three teams numbered passing sequence with pressers', 'possession', 'opposed', 'in_possession', 105, 105, 'Practice 48', 'FC Barcelona', 'Awareness and problem solving in a chaotic, crowded space.', 'One area with 3 teams of 4 (players secretly numbered 1-4), 2 pressing defenders and 2 resting players.', 'Coach calls a sequence (e.g. 1, 4, 3, 2); each team passes in that order. First team to complete it without losing the ball wins a point. Pressers chase any team at high tempo and rotate with the resting pair.', 'Pressers may not man-mark one player or focus on one team.', NULL, 'Peripheral vision under chaos; head up and scan over the shoulder; use the whole area; think of the third man.', '3 teams of 4 + 2 pressers + 2 resting', 16, 16, NULL, NULL, NULL, NULL, false, false, false, NULL, 480),
  ('Four squares 3v1 or 2v2 problem solvers', 'possession', 'opposed', 'in_possession', 106, 106, 'Practice 49', 'FC Barcelona', 'Problem solving for the player on the ball in a chaotic setting.', 'Space split into 4 equal squares with 3 players in each who secretly decide which 2 are a team; plus 3 problem solvers who move between squares.', 'A problem solver passes into a square: if it goes to the pair it becomes 3v1, if to the lone player it becomes 2v2. Squares react at once; 5 passes for the solver''s team scores 1. On the coach''s call the ball moves clockwise; after 4 rotations new solvers.', 'Defenders commit immediately.', 'Solvers limited to 2 touches; remove a cone line to make 1 large and 2 small spaces.', NULL, '15 (4 x 3 + 3 problem solvers)', 15, 15, NULL, NULL, NULL, NULL, false, false, false, NULL, 490),
  ('Four corner zones defence to attack', 'transition', 'overload', 'to_attack', 107, 107, 'Practice 50', 'FC Barcelona', 'Recreate the pressure of fast transition from defence to attack.', '8 corner-type zones (diagram): 4 contain a small cone goal, the other 4 hold one player each; in the centre 2 floating possession players and 3 opponents.', 'The 2 floaters join a corner player to keep the ball 3v1 against a defender who sprints in from the middle. If he wins it, he plays out fast to his 2 waiting team-mates, who attack and try to score in one of the 3 cone goals; the goal''s guard steps out to pressure.', '1 point per goal or per 4 passes completed in the 3v1. Rotate after each attack.', 'Run 2 games corner to corner at the same time for more chaos.', 'Corner goal guard pressures the attackers instead of just guarding the goal.', '9 (4 corner + 2 floaters + 3 opponents)', 9, 9, NULL, NULL, NULL, NULL, true, false, true, NULL, 500)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
JOIN exercise_categories c ON c.code = v.cat
CROSS JOIN (SELECT id, source_id FROM coaching_books WHERE slug = 'coaching-the-tiki-taka-style-of-play') b;
INSERT INTO schema_migrations (filename) VALUES ('2220-exercises-book-coaching-the-tiki-taka-style-of-play.sql') ON CONFLICT DO NOTHING;
COMMIT;
